// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 1 ether);

        vm.prank(user);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success);

        address target = address(0x5678);
        uint value = 0;
        bytes memory data = "";
        c.sendMoney(target, value, data);

        uint256 count = c.depositsCount();
        assertTrue(count == 1, "depositsCount should be 1 after one fallback");
    }
}
